// src/components/ai/GeminiAI.js
// 100% FREE Google Gemini AI Integration

const GEMINI_API_KEY = process.env.REACT_APP_GEMINI_API_KEY || 'AIzaSyCw8Ev0vGtvzxCbzGxrhUUASaVSfxvaDj4';
const GEMINI_API_URL = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent';

export const generateInterviewQuestions = async (resumeText, jobRole = 'Software Developer') => {
  try {
    const prompt = `Based on this resume, generate exactly 5 technical interview questions for a ${jobRole} position. 
    Make questions progressively harder (Easy, Medium, Medium, Hard, Hard).

    Resume:
    ${resumeText}

    Return ONLY valid JSON in this exact format:
    [
      {
        "id": 1,
        "question": "question text here",
        "difficulty": "Easy",
        "time": 90,
        "expectedKeywords": ["keyword1", "keyword2"]
      }
    ]`;

    const response = await fetch(`${GEMINI_API_URL}?key=${GEMINI_API_KEY}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        contents: [{
          parts: [{
            text: prompt
          }]
        }],
        generationConfig: {
          temperature: 0.7,
          maxOutputTokens: 2048,
        }
      })
    });

    if (!response.ok) {
      throw new Error(`Gemini API error: ${response.status}`);
    }

    const data = await response.json();
    const textResponse = data.candidates[0].content.parts[0].text;

    // Extract JSON from response
    const jsonMatch = textResponse.match(/\[[\s\S]*\]/);
    if (!jsonMatch) {
      throw new Error('Failed to parse questions from AI response');
    }

    const questions = JSON.parse(jsonMatch[0]);
    return questions;

  } catch (error) {
    console.error('Gemini AI Error:', error);
    // Fallback to default questions
    return getDefaultQuestions();
  }
};

export const scoreAnswerWithAI = async (question, answer, difficulty) => {
  try {
    const prompt = `Evaluate this interview answer and give a score out of ${
      difficulty === 'Easy' ? 10 : difficulty === 'Medium' ? 20 : 30
    } points.

Question: ${question}
Answer: ${answer}
Difficulty: ${difficulty}

Return ONLY valid JSON:
{
  "score": number,
  "feedback": "brief feedback"
}`;

    const response = await fetch(`${GEMINI_API_URL}?key=${GEMINI_API_KEY}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        contents: [{
          parts: [{
            text: prompt
          }]
        }],
        generationConfig: {
          temperature: 0.3,
          maxOutputTokens: 256,
        }
      })
    });

    if (!response.ok) {
      throw new Error(`Gemini API error: ${response.status}`);
    }

    const data = await response.json();
    const textResponse = data.candidates[0].content.parts[0].text;

    const jsonMatch = textResponse.match(/\{[\s\S]*\}/);
    if (!jsonMatch) {
      return getFallbackScore(answer, difficulty);
    }

    return JSON.parse(jsonMatch[0]);

  } catch (error) {
    console.error('AI Scoring Error:', error);
    return getFallbackScore(answer, difficulty);
  }
};

const getFallbackScore = (answer, difficulty) => {
  const wordCount = answer.trim().split(/\s+/).length;
  const baseScore = difficulty === 'Easy' ? 10 : difficulty === 'Medium' ? 20 : 30;
  const minWords = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 40 : 60;

  let score = baseScore;
  if (wordCount < minWords * 0.3) score = Math.floor(baseScore * 0.3);
  else if (wordCount < minWords * 0.6) score = Math.floor(baseScore * 0.6);
  else if (wordCount >= minWords) score = baseScore;
  else score = Math.floor(baseScore * 0.8);

  return {
    score,
    feedback: wordCount < minWords ? 'Answer could be more detailed' : 'Good answer!'
  };
};

const getDefaultQuestions = () => [
  {
    id: 1,
    question: "Tell me about yourself and your background.",
    difficulty: "Easy",
    time: 90,
    expectedKeywords: ["experience", "skills", "education"]
  },
  {
    id: 2,
    question: "What are your greatest strengths as a developer?",
    difficulty: "Medium",
    time: 120,
    expectedKeywords: ["problem-solving", "technical", "teamwork"]
  },
  {
    id: 3,
    question: "Describe a challenging project you worked on.",
    difficulty: "Medium",
    time: 150,
    expectedKeywords: ["challenge", "solution", "result"]
  },
  {
    id: 4,
    question: "How do you handle tight deadlines and pressure?",
    difficulty: "Hard",
    time: 180,
    expectedKeywords: ["prioritize", "manage", "communicate"]
  },
  {
    id: 5,
    question: "Where do you see yourself in 5 years?",
    difficulty: "Hard",
    time: 120,
    expectedKeywords: ["growth", "goals", "development"]
  }
];
